import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = join(HERE, '..', 'data');
const FILE = join(DATA_DIR, 'books.json');

let writeChain = Promise.resolve();

async function ensureFile() {
  await mkdir(DATA_DIR, { recursive: true });
  try {
    await readFile(FILE, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      await writeFile(FILE, '[]\n', 'utf8');
    } else {
      throw err;
    }
  }
}

async function readAll() {
  await ensureFile();
  const raw = await readFile(FILE, 'utf8');
  const parsed = JSON.parse(raw);
  return Array.isArray(parsed) ? parsed : [];
}

function writeAll(books) {
  const next = writeChain.then(async () => {
    await ensureFile();
    await writeFile(FILE, JSON.stringify(books, null, 2) + '\n', 'utf8');
  });
  writeChain = next.catch(() => {});
  return next;
}

function nowIso() {
  return new Date().toISOString();
}

export async function listBooks() {
  return readAll();
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function createBook({ title, author, notes }) {
  const book = {
    id: randomUUID(),
    title: String(title ?? '').trim(),
    author: String(author ?? '').trim(),
    notes: String(notes ?? ''),
    status: 'reading',
    createdAt: nowIso(),
    finishedAt: null,
  };
  const books = await readAll();
  books.push(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = 'finished';
  book.finishedAt = nowIso();
  await writeAll(books);
  return book;
}

export async function reopenBook(id) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = 'reading';
  book.finishedAt = null;
  await writeAll(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = String(notes ?? '');
  await writeAll(books);
  return book;
}

