const esc = (s) =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const styles = `
  :root { color-scheme: light dark; }
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    max-width: 760px;
    margin: 0 auto;
    padding: 2rem 1.25rem 4rem;
    line-height: 1.5;
  }
  h1 { font-size: 1.6rem; margin: 0 0 1rem; }
  h2 { font-size: 1.15rem; margin: 1.5rem 0 0.5rem; }
  a { color: #2563eb; }
  .topbar { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  .book-list { list-style: none; padding: 0; margin: 0; }
  .book-list li {
    padding: 0.6rem 0;
    border-bottom: 1px solid #e5e7eb;
    display: flex;
    justify-content: space-between;
    gap: 0.75rem;
  }
  .book-list li:last-child { border-bottom: none; }
  .book-title { font-weight: 600; }
  .book-author { color: #6b7280; font-size: 0.92rem; }
  .empty { color: #6b7280; font-style: italic; padding: 0.5rem 0; }
  .actions { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-top: 1rem; }
  button, .button {
    font: inherit;
    background: #111827;
    color: #fff;
    border: none;
    padding: 0.45rem 0.9rem;
    border-radius: 6px;
    cursor: pointer;
    text-decoration: none;
    display: inline-block;
  }
  button.secondary, .button.secondary {
    background: transparent;
    color: #111827;
    border: 1px solid #d1d5db;
  }
  form { display: grid; gap: 0.75rem; margin-top: 0.5rem; }
  label { font-weight: 600; font-size: 0.92rem; }
  input[type="text"], textarea {
    font: inherit;
    width: 100%;
    padding: 0.5rem 0.6rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    background: #fff;
  }
  textarea { min-height: 6rem; resize: vertical; }
  .meta { color: #6b7280; font-size: 0.88rem; }
  .badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 999px;
    font-size: 0.78rem;
    background: #e5e7eb;
    color: #374151;
  }
  .badge.done { background: #dcfce7; color: #166534; }
  .notes {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    border: 1px solid #e5e7eb;
  }
`;

export function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)}</title>
  <style>${styles}</style>
</head>
<body>
  <div class="topbar">
    <a href="/" style="text-decoration:none;color:inherit;"><h1>My Books</h1></a>
    <a class="button" href="/books/new">Add book</a>
  </div>
  ${body}
</body>
</html>`;
}

function formatDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

function bookItem(book) {
  const author = book.author ? `<div class="book-author">${esc(book.author)}</div>` : '';
  const finished = book.status === 'finished'
    ? `<span class="badge done">finished</span>`
    : `<span class="badge">reading</span>`;
  return `<li>
    <div>
      <a class="book-title" href="/books/${esc(book.id)}">${esc(book.title)}</a>
      ${author}
    </div>
    ${finished}
  </li>`;
}

export function homePage(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));

  const readingHtml = reading.length
    ? `<ul class="book-list">${reading.map(bookItem).join('')}</ul>`
    : `<p class="empty">Nothing in progress. Add a book to get started.</p>`;

  const finishedHtml = finished.length
    ? `<ul class="book-list">${finished.map(bookItem).join('')}</ul>`
    : `<p class="empty">No finished books yet.</p>`;

  return layout(
    'My Books',
    `
      <h2>Currently reading (${reading.length})</h2>
      ${readingHtml}
      <h2>Finished (${finished.length})</h2>
      ${finishedHtml}
    `
  );
}

export function newBookForm({ values = {}, errors = [] } = {}) {
  const v = (key) => esc(values[key] ?? '');
  const errHtml = errors.length
    ? `<ul style="color:#b91c1c;margin:0 0 0.75rem;">${errors.map((e) => `<li>${esc(e)}</li>`).join('')}</ul>`
    : '';
  return layout(
    'Add a book',
    `
      <h2>Add a book</h2>
      ${errHtml}
      <form method="post" action="/books">
        <div>
          <label for="title">Title</label>
          <input id="title" name="title" type="text" value="${v('title')}" required>
        </div>
        <div>
          <label for="author">Author</label>
          <input id="author" name="author" type="text" value="${v('author')}">
        </div>
        <div>
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Why are you reading it? What do you think so far?">${v('notes')}</textarea>
        </div>
        <div class="actions">
          <button type="submit">Add book</button>
          <a class="button secondary" href="/">Cancel</a>
        </div>
      </form>
    `
  );
}

export function bookDetailPage(book) {
  const finishedBadge = book.status === 'finished'
    ? `<span class="badge done">finished ${esc(formatDate(book.finishedAt))}</span>`
    : `<span class="badge">reading since ${esc(formatDate(book.createdAt))}</span>`;

  const finishAction = book.status === 'reading'
    ? `<form method="post" action="/books/${esc(book.id)}/finish" style="display:inline;">
         <button type="submit">Mark as finished</button>
       </form>`
    : `<form method="post" action="/books/${esc(book.id)}/reopen" style="display:inline;">
         <button type="submit" class="secondary">Move back to reading</button>
       </form>`;

  const authorLine = book.author
    ? `<p class="meta">by ${esc(book.author)}</p>`
    : '';

  const notesHtml = (book.notes ?? '').trim()
    ? `<div class="notes">${esc(book.notes)}</div>`
    : `<p class="meta"><em>No notes yet.</em></p>`;

  return layout(
    book.title,
    `
      <p><a href="/">&larr; All books</a></p>
      <h2>${esc(book.title)}</h2>
      ${authorLine}
      <p>${finishedBadge}</p>

      <h2>Notes</h2>
      ${notesHtml}

      <form method="post" action="/books/${esc(book.id)}/notes" style="margin-top:1rem;">
        <label for="notes">Update notes</label>
        <textarea id="notes" name="notes">${esc(book.notes ?? '')}</textarea>
        <div class="actions">
          <button type="submit">Save notes</button>
          ${finishAction}
          <a class="button secondary" href="/books/${esc(book.id)}">Refresh</a>
        </div>
      </form>
    `
  );
}

export function notFoundPage(message = 'Not found') {
  return layout(
    message,
    `
      <p>${esc(message)}.</p>
      <p><a href="/">Back to my books</a></p>
    `
  );
}

