import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import * as store from './lib/store.js';
import * as views from './lib/views.js';

const PORT = Number(process.env.PORT) || 3000;
const HOST = process.env.HOST || '127.0.0.1';

function send(res, status, body, headers = {}) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'content-length': Buffer.byteLength(body, 'utf8'),
    ...headers,
  });
  res.end(body);
}

function redirect(res, location, status = 303) {
  res.writeHead(status, { location });
  res.end();
}

async function readFormBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    const limit = 64 * 1024;
    req.on('data', (chunk) => {
      total += chunk.length;
      if (total > limit) {
        req.destroy();
        reject(new Error('Request body too large'));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      const params = new URLSearchParams(raw);
      resolve(Object.fromEntries(params.entries()));
    });
    req.on('error', reject);
  });
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const routes = [
  {
    match: (m, u) => m === 'GET' && u.pathname === '/',
    handle: async (req, res) => {
      const books = await store.listBooks();
      send(res, 200, views.homePage(books));
    },
  },
  {
    match: (m, u) => m === 'GET' && u.pathname === '/books/new',
    handle: async (req, res) => {
      send(res, 200, views.newBookForm());
    },
  },
  {
    match: (m, u) => m === 'POST' && u.pathname === '/books',
    handle: async (req, res) => {
      const form = await readFormBody(req);
      const title = (form.title || '').trim();
      const author = (form.author || '').trim();
      const notes = form.notes || '';
      const errors = [];
      if (!title) errors.push('Title is required.');
      if (errors.length) {
        send(res, 400, views.newBookForm({ values: { title, author, notes }, errors }));
        return;
      }
      const book = await store.createBook({ title, author, notes });
      redirect(res, `/books/${book.id}`);
    },
  },
  {
    match: (m, u) =>
      m === 'GET' && u.pathname.startsWith('/books/') &&
      UUID_RE.test(u.pathname.slice('/books/'.length)) &&
      u.pathname.length === '/books/'.length + 36,
    handle: async (req, res, u) => {
      const id = u.pathname.slice('/books/'.length);
      const book = await store.getBook(id);
      if (!book) {
        send(res, 404, views.notFoundPage('Book not found'));
        return;
      }
      send(res, 200, views.bookDetailPage(book));
    },
  },
  {
    match: (m, u) => {
      if (m !== 'POST') return false;
      const prefix = '/books/';
      const suffix = '/finish';
      const path = u.pathname;
      if (!path.startsWith(prefix) || !path.endsWith(suffix)) return false;
      const id = path.slice(prefix.length, path.length - suffix.length);
      return UUID_RE.test(id);
    },
    handle: async (req, res, u) => {
      const path = u.pathname;
      const id = path.slice('/books/'.length, path.length - '/finish'.length);
      await readFormBody(req);
      const book = await store.markFinished(id);
      if (!book) {
        send(res, 404, views.notFoundPage('Book not found'));
        return;
      }
      redirect(res, `/books/${id}`);
    },
  },
  {
    match: (m, u) => {
      if (m !== 'POST') return false;
      const prefix = '/books/';
      const suffix = '/reopen';
      const path = u.pathname;
      if (!path.startsWith(prefix) || !path.endsWith(suffix)) return false;
      const id = path.slice(prefix.length, path.length - suffix.length);
      return UUID_RE.test(id);
    },
    handle: async (req, res, u) => {
      const path = u.pathname;
      const id = path.slice('/books/'.length, path.length - '/reopen'.length);
      await readFormBody(req);
      const book = await store.reopenBook(id);
      if (!book) {
        send(res, 404, views.notFoundPage('Book not found'));
        return;
      }
      redirect(res, `/books/${id}`);
    },
  },
  {
    match: (m, u) => {
      if (m !== 'POST') return false;
      const prefix = '/books/';
      const suffix = '/notes';
      const path = u.pathname;
      if (!path.startsWith(prefix) || !path.endsWith(suffix)) return false;
      const id = path.slice(prefix.length, path.length - suffix.length);
      return UUID_RE.test(id);
    },
    handle: async (req, res, u) => {
      const path = u.pathname;
      const id = path.slice('/books/'.length, path.length - '/notes'.length);
      const form = await readFormBody(req);
      const book = await store.updateNotes(id, form.notes || '');
      if (!book) {
        send(res, 404, views.notFoundPage('Book not found'));
        return;
      }
      redirect(res, `/books/${id}`);
    },
  },
];

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const route = routes.find((r) => r.match(req.method, url));
    if (!route) {
      send(res, 404, views.notFoundPage('Page not found'));
      return;
    }
    await route.handle(req, res, url);
  } catch (err) {
    console.error(err);
    if (!res.headersSent) {
      send(res, 500, views.notFoundPage('Something went wrong'));
    } else {
      res.end();
    }
  }
});

server.listen(PORT, HOST, () => {
  console.log(`My Books running at http://${HOST}:${PORT}`);
});

export { server };

